    function openProjectsProductGallery(productIndex) {
        const product = currentProjectsProducts[productIndex];
        const gallery = product && product.gallery;

        if (!gallery || !gallery.length) {
            return;
        }

        const groupName = 'project-gallery-' + currentProjectsCategoryIndex + '-' + productIndex;
        const $galleryLinks = $('<div class="projects-fancybox-gallery" hidden></div>');

        gallery.forEach(function(src, imageIndex) {
            $('<a></a>')
                .attr('href', src)
                .attr('rel', groupName)
                .attr('data-fancybox-type', 'image')
                .attr('title', (imageIndex + 1) + ' / ' + gallery.length)
                .appendTo($galleryLinks);
        });

        $('body').append($galleryLinks);

        $galleryLinks.find('a').fancybox({
            padding: 0,
            index: 0,
            helpers: {
                overlay: {
                    locked: false
                }
            },
            afterClose: function() {
                $galleryLinks.remove();
            }
        });

        $galleryLinks.find('a').eq(0).trigger('click');
    }

    function renderProjectsProductInfo(categoryIndex, slideIndex) {
        const infos = projectsProductInfo[categoryIndex];
        const info = infos && infos[slideIndex];

        closeProjectsInfoPanel();

        if (!info) {
            $projectsInfoBtn.attr('hidden', true);
            $projectsInfo.attr('hidden', true);
            $projectsInfoContent.empty();
            return;
        }

        let html = '';
        if (info.title) {
            html += '<p class="modal-projects__info-title">' + info.title + '</p>';
        }
        html += '<ul class="modal-projects__info-list">';
        info.details.forEach(function(item) {
            html += '<li><span class="modal-projects__info-term">' + item.label + ':</span> ' + item.value + '</li>';
        });
        if (info.cost) {
            html += '<li class="modal-projects__info-meta"><span class="modal-projects__info-term">Стоимость:</span> ' + info.cost + '</li>';
        }
        if (info.realization) {
            html += '<li class="modal-projects__info-meta"><span class="modal-projects__info-term">Реализация:</span> ' + info.realization + '</li>';
        }
        html += '</ul>';

        $projectsInfoContent.html(html);
        $projectsInfoBtn.removeAttr('hidden');
        $projectsInfo.removeAttr('hidden');
    }

    function openProjectsModal($item) {
        const title = $item.data('title') || '';
        const index = parseInt($item.data('index'), 10) || 1;
        const products = projectsSlides[index] || projectsSlides[1];
        currentProjectsCategoryIndex = index;
        currentProjectsProducts = products;

        $projectsTitle.text(title);
        renderProjectsProductInfo(index, 0);
        $projectsSwiperWrapper.empty();
        products.forEach(function(product, productIndex) {
            const src = product.cover || product.gallery[0];
            const info = projectsProductInfo[index] && projectsProductInfo[index][productIndex];
            const alt = info && info.title ? info.title : title;

            $projectsSwiperWrapper.append(
                '<div class="swiper-slide">' +
                '<button type="button" class="modal-projects__gallery-trigger js-projects-gallery-trigger" data-product-index="' + productIndex + '" aria-label="Открыть все фото товара">' +
                '<img src="' + src + '" alt="' + alt + '">' +
                '</button>' +
                '</div>'
            );
        });

        if (projectsSwiperInstance) {
            projectsSwiperInstance.destroy(true, true);
            projectsSwiperInstance = null;
        }

        $modalProjects.addClass('active');
        $('body').css('overflow', 'hidden');
        $modalProjects.find('.js-close-modal').off('click').on('click', closeProjectsModal);

        setTimeout(function() {
            projectsSwiperInstance = new Swiper('.swiper--projects', {
                slidesPerView: 1,
                spaceBetween: 0,
                autoHeight: true,
                loop: products.length > 1,
                pagination: {
                    el: '.modal-projects__pagination',
                    clickable: true
                },
                navigation: {
                    nextEl: '.swiper-button-next--projects',
                    prevEl: '.swiper-button-prev--projects'
                },
                on: {
                    init: function() {
                        this.updateAutoHeight();
                    },
                    slideChange: function() {
                        this.updateAutoHeight();
                        renderProjectsProductInfo(currentProjectsCategoryIndex, this.realIndex);
                    }
                }
            });

            function updateProjectsSwiperHeight() {
                if (projectsSwiperInstance) {
                    projectsSwiperInstance.updateAutoHeight();
                }
            }

            $projectsSwiperWrapper.find('img').on('load', updateProjectsSwiperHeight);
            $projectsSwiperWrapper.find('img').each(function() {
                if (this.complete) {
                    updateProjectsSwiperHeight();
                }
            });
        }, 50);
    }

